def solve():
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    N = int(data[0])
    a = []
    for i in range(N):
        a.append(int(data[i + 1]))

    # Sort the cards in descending order
    a.sort(reverse=True)

    alice_score = 0
    bob_score = 0

    for i in range(N):
        if i % 2 == 0:
            alice_score += a[i]
        else:
            bob_score += a[i]

    print(alice_score - bob_score)

if __name__ == "__main__":
    solve()

